///|
/// Split a script into statements (SPEC §2.2). Pieces with only whitespace
/// and comments are dropped.
pub fn split_statements(s : String) -> Array[String] {
  let out : Array[String] = []
  let n = s.length()
  let mut i = 0
  let mut start = 0
  let mut has_content = false
  while i < n {
    let c = s[i]
    if c == '-' && i + 1 < n && s[i + 1] == '-' {
      while i < n && s[i] != '\n' {
        i += 1
      }
      continue
    }
    if c == '/' && i + 1 < n && s[i + 1] == '*' {
      i += 2
      while i < n && !(s[i] == '*' && i + 1 < n && s[i + 1] == '/') {
        i += 1
      }
      i = if i < n { i + 2 } else { n }
      continue
    }
    if c == '\'' || c == '"' || c == '`' || c == '[' {
      has_content = true
      let close = if c == '[' { ']'.to_int() } else { c.to_int() }
      i += 1
      while i < n {
        if s[i].to_int() == close {
          if close != ']'.to_int() && i + 1 < n && s[i + 1].to_int() == close {
            i += 2
            continue
          }
          break
        }
        i += 1
      }
      i += 1
      continue
    }
    if c == ';' {
      if has_content {
        out.push(s[start:i].to_owned())
      }
      i += 1
      start = i
      has_content = false
      continue
    }
    if !is_space_cu(c) {
      has_content = true
    }
    i += 1
  }
  if has_content && start < n {
    out.push(s[start:].to_owned())
  }
  out
}
