///|
/// SQLite's patternCompare for LIKE (case-insensitive for ASCII, `%`, `_`,
/// optional escape) and GLOB (`*`, `?`, `[...]`).
fn pattern_match(
  pat : Array[Char],
  pi : Int,
  s : Array[Char],
  si : Int,
  glob : Bool,
  esc : Char?,
) -> Bool {
  let np = pat.length()
  let ns = s.length()
  let mut pi = pi
  let mut si = si
  while pi < np {
    let c = pat[pi]
